def transform(grid):
    """Connect aligned occurrences of non-modal tile colors through blank cells."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for color in row:
            if color:
                counts[color] = counts.get(color, 0) + 1
    frame = max(counts, key=counts.get)
    inner_counts = {c: n for c, n in counts.items() if c != frame}
    common = max(inner_counts, key=inner_counts.get)
    positions = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color not in (0, frame, common):
                positions.setdefault(color, []).append((r, c))
    for color, cells in positions.items():
        for i, (r1, c1) in enumerate(cells):
            for r2, c2 in cells[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2) + 1, max(c1, c2)):
                        if out[r1][c] == 0:
                            out[r1][c] = color
                elif c1 == c2:
                    for r in range(min(r1, r2) + 1, max(r1, r2)):
                        if out[r][c1] == 0:
                            out[r][c1] = color
    return out
